def toy_rows(n, seed):
    """Easy-to-separate router data: label 0 for simple queries, 1 for hard ones."""
    rng = random.Random(seed)
    rows = [(rng.choice(SIMPLE), 0) if i % 2 == 0 else (rng.choice(HARD), 1) for i in range(n)]
    return {TEXT_COLUMN: [text for text, _ in rows], LABEL_COLUMN: [label for _, label in rows]}

