def preview(items):
    items = [str(x) for x in items]
    more = len(items) - MAX_LISTED
    return "\n".join(items[:MAX_LISTED] + ([f"... ({more} more)"] if more > 0 else []))

# Data labeling

def sample_people(title_to_text, num_people=NUM_PEOPLE, seed=SEED):
    """The same num_people names every run, for the same seed and title_to_text."""
    names = sorted(title_to_text)
    return random.Random(seed).sample(names, min(num_people, len(names)))


@contextlib.contextmanager
def no_text_processing(fn):
    """Switches text_processing_function off in fn's globals while the block runs, then restores it."""
    namespace = getattr(fn, "__globals__", {})
    missing = object()
    saved = namespace.get(TEXT_FUNCTION_NAME, missing)
    namespace[TEXT_FUNCTION_NAME] = lambda text, *args, **kwargs: text
    try:
        yield
    finally:
        if saved is missing:
            del namespace[TEXT_FUNCTION_NAME]
        else:
            namespace[TEXT_FUNCTION_NAME] = saved


def words(text):
    """The lowercased words of text, as a tuple: spaCy tokens without punctuation or whitespace."""
    return tuple(t.text.lower() for t in nlp.make_doc(str(text)) if not t.is_punct and not t.is_space)


def sentence_words(text):
    """words() of each sentence of text, as spaCy splits them."""
    return [words(sent.text) for sent in nlp(text).sents]


def mentions_fact(name, title_to_text, db_split):
    """Whether name's text contains one of their db_split values for the relations in SELECTED_RELATIONS."""
    text = title_to_text[name].lower()
    values = [str(value) for relation, value in (db_split.get(name) or {}).items() if relation in SELECTED_RELATIONS]
    return any(part.strip().lower() in text for value in values for part in value.split(";") if part.strip())


def fact_targets(name):
    """FACT_PREFIXES[name] as one set of word tuples per fact. Empty for anyone but the test people."""
    return [{words(prefix) for prefix in prefixes} for prefixes in FACT_PREFIXES.get(name, ())]


def text_processing_inputs(title_to_text, people):
    """The texts test 1.5 passes to text_processing_function: a few fixed ones, then every sentence of
    each person's text."""
    return list(TEXT_PROCESSING_INPUTS) + [sent.text for name in people for sent in nlp(title_to_text[name]).sents]


def show(word_tuple):
    return repr(" ".join(word_tuple))


def structure_problems(output):
    """Return (problems, deduction); empty problems means OK."""
    if not isinstance(output, list):
        return [f"Records should be a list; got {type(output).__name__}."], 1
    problems = []
    wrong_element_type = 0
    missing_key = 0
    wrong_data_types = 0
    for i, el in enumerate(output):
        if not isinstance(el, dict):
            problems.append(f"Record {i} should be a dict; got {type(el).__name__}.")
            wrong_element_type = 1
            continue
        for key in CRUCIAL_KEYS:
            if key not in el:
                problems.append(f"Record {i} is missing {key!r}: {el!r}")
                missing_key = 0.5
        if "text" in el and not isinstance(el.get("text"), str):
            problems.append(f"Record {i}: 'text' should be a str; got {type(el.get('text')).__name__}.")
            wrong_data_types = 0.5
        if "label" in el:
            label = el.get("label")
            if isinstance(label, bool) or not isinstance(label, int) or label not in ALLOWED_LABELS:
                problems.append(f"Record {i}: 'label' should be 0 or 1; got {label!r}.")
                wrong_data_types = 0.5
    return problems, wrong_data_types + wrong_element_type + missing_key


def coverage_problems(output, targets=()):
    """Return (problems, fraction of required prefixes that are present), or ([], None) when there
    is nothing to check.

    Required: every word-level prefix up to each positive record, and, for each fact in targets
    (from fact_targets), every prefix up to that fact.
    """
    if not isinstance(output, list):
        return [f"Records should be a list; got {type(output).__name__}."], 0
    records = [r for r in output if isinstance(r, dict) and isinstance(r.get("text"), str)]
    present = {words(r.get("text")) for r in records}
    positives = {words(r.get("text")) for r in records if r.get("label") == 1}
    replaced = {p[:-1] for p in positives}  # prefixes a one-word-longer positive stands in for

    required = set()
    for p in positives | {max(t, key=len) for t in targets}:
        required |= {p[:k] for k in range(1, len(p) + 1)}

    if not required:
        return [], None  # no fact to check and no positive record: nothing to check
    missing = sorted((w for w in required if w not in present and w not in replaced), key=len)
    problems = [f"Missing prefix {show(w)}" for w in missing]
    return problems, 1 - len(missing) / len(required)


def labeling_counts(output, targets):
    """Return (facts found, facts, right positives, positives, problems) for one person."""
    records = [r for r in output if isinstance(r, dict) and isinstance(r.get("text"), str)] if isinstance(output, list) else []
    positives = {words(r.get("text")) for r in records if r.get("label") == 1}
    missed = [max(t, key=len) for t in targets if not t & positives]
    wrong = positives - set().union(*targets)
    problems = [f"Should be label 1, a fact comes next: {show(w)}" for w in sorted(missed, key=len)]
    problems += [f"Should be label 0, no fact comes next: {show(w)}" for w in sorted(wrong, key=len)]
    return len(targets) - len(missed), len(targets), len(positives) - len(wrong), len(positives), problems


def label_f1(found, facts, right, positives):
    recall, precision = found / facts if facts else 0, right / positives if positives else 0
    return 2 * recall * precision / (recall + precision) if recall + precision else 0


def labeling_problems(output):
    """Return problems; labels must include both 0s and 1s."""
    labels = [el.get("label") for el in output if isinstance(el, dict)]
    if 0 not in labels or 1 not in labels:
        return [f"Labels should include both 0 and 1; got {sorted({str(label) for label in labels}) or 'none'}."]
    return []


def title_to_text_problems(output, text):
    """Return problems; every text must be a non-empty word-level prefix of a sentence of `text`,
    split by spaCy or by a plain regex: either way of splitting is fine."""
    if not output:
        return ["No records returned."]
    sentences = sentence_words(text) + [words(s) for s in SENTENCE_END.split(text)]
    bad = [el.get("text") for el in output if isinstance(el, dict)
           and not (isinstance(el.get("text"), str) and words(el.get("text"))
                    and any(s[:len(words(el.get("text")))] == words(el.get("text")) for s in sentences))]
    if bad:
        return [f"{len(bad)} text(s) are not prefixes of a sentence in this person's text:\n{preview(bad)}"]
    return []

# Router training

class SpyTokenizer(BertTokenizer):
    """The tiny model's tokenizer, recording every call that tokenizes text. It is a real
    tokenizer subclass, so Trainer and data collators treat it as usual."""

    def __call__(self, text=None, *args, **kwargs):
        if text is not None:
            self.__dict__.setdefault("text_calls", []).append(kwargs)
        return super().__call__(text, *args, **kwargs)


def spy_tokenizer():
    tokenizer = SpyTokenizer.from_pretrained(TINY_MODEL)
    tokenizer.text_calls = []
    return tokenizer


class TimeLimitExceeded(Exception):
    pass


def call_with_time_limit(fn, *args):
    """Windows has no SIGALRM, so there is no limit there."""
    if not hasattr(signal, "SIGALRM"):
        return fn(*args)

    def on_timeout(signum, frame):
        raise TimeLimitExceeded()

    previous = signal.signal(signal.SIGALRM, on_timeout)
    signal.alarm(TIME_LIMIT_SECONDS)
    try:
        return fn(*args)
    finally:
        signal.alarm(0)
        signal.signal(signal.SIGALRM, previous)


def call_student(fn, name, *args):
    """Calls the student's function. Returns (result, error_message)."""
    if not callable(fn):
        return None, f"{name} is not defined. Don't rename or delete it."
    try:
        return call_with_time_limit(fn, *args), None
    except TimeLimitExceeded:
        return None, f"{name} took longer than {TIME_LIMIT_SECONDS}s on the test data."
    except Exception as e:
        message = f"{name} raised {type(e).__name__}: {e}"
        if "fp16" in str(e).lower() or "bf16" in str(e).lower():
            message += "\nThe checks run on a CPU. Use fp16=torch.cuda.is_available() instead of fp16=True."
        if "eval_f1" in str(e):
            message += '\ncompute_metrics should return a dict with an "f1" key.'
        return None, message


def pretrained_loads(fn, kind):
    """The .from_pretrained(...) calls inside fn whose receiver mentions `kind`,
    e.g. ['AutoTokenizer.from_pretrained'] for kind="Tokenizer"."""
    try:
        tree = ast.parse(textwrap.dedent(inspect.getsource(fn)))
    except (OSError, TypeError, SyntaxError):
        return []
    calls = {ast.unparse(n.func) for n in ast.walk(tree) if isinstance(n, ast.Call)}
    return sorted(c for c in calls if c.endswith("from_pretrained") and kind.lower() in c.lower())


def flat(value):
    """value as one flat list, so a label wrapped as [label] counts like a bare one."""
    return [x for item in value for x in flat(item)] if isinstance(value, list) else [value]


def plain(value):
    """value as plain Python data: lists, ints, floats, strings, bools and None."""
    value = getattr(value, "value", value)  # enums such as IntervalStrategy.EPOCH -> "epoch"
    if hasattr(value, "tolist"):
        return value.tolist()
    if isinstance(value, Mapping):
        return {str(k): plain(v) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [plain(v) for v in value]
    if value is None or isinstance(value, (bool, int, float, str)):
        return value
    if isinstance(value, numbers.Number):
        return float(value)
    return str(value)


def column(out, key, single):
    """out[key] as a list with one entry per example, or None if out has no such key."""
    if not isinstance(out, Mapping) or key not in out:  # tokenizer output is a Mapping, not a dict
        return None
    value = plain(out[key])
    return [value] if single else list(value)


def tokenized(dataset, tokenize_record, tokenizer):
    """The toy dataset tokenized with the student's tokenize_record, as their notebook does before
    calling train_router: batched first, then one example at a time. If tokenize_record does not work
    either way, plain tokenization is used instead, so its bugs cost points only in tests 2.1-2.3."""
    if callable(tokenize_record):
        for batched in (True, False):
            try:
                out = dataset.map(lambda batch: tokenize_record(batch, tokenizer, TRAINING_MAX_LENGTH),
                                  batched=batched, remove_columns=[TEXT_COLUMN])
            except Exception:
                continue
            if "input_ids" in out.column_names:
                return out
    return dataset.map(lambda batch: tokenizer(batch[TEXT_COLUMN]), batched=True, remove_columns=[TEXT_COLUMN])


def toy_dev_logits(model):
    """The model's logits on the toy dev texts."""
    tokenizer = BertTokenizer.from_pretrained(TINY_MODEL)
    inputs = tokenizer(toy_rows(32, seed=2)[TEXT_COLUMN], padding=True, return_tensors="pt")
    model.eval()
    with torch.no_grad():
        return model(**inputs.to(model.device)).logits.cpu()


def toy_dev_loss(logits, shift=0.0):
    labels = torch.tensor(toy_rows(32, seed=2)[LABEL_COLUMN])
    return torch.nn.functional.cross_entropy(logits + torch.tensor([0.0, shift]), labels).item()


def best_bias_only_loss(logits):
    """The lowest loss reachable by shifting the class-1 logit by a constant, i.e. by changing
    only the output bias. A model must beat this to show it learned from the text."""
    return min(toy_dev_loss(logits, shift / 100) for shift in range(-1000, 1001, 5))


def toy_dev_auc(logits):
    """How well the class-1 score ranks the hard toy queries above the simple ones (1.0 is perfect)."""
    return roc_auc_score(toy_rows(32, seed=2)[LABEL_COLUMN], (logits[:, 1] - logits[:, 0]).numpy())

