# TrainingArguments fields you set when filling in train_router. If none differs from its default,
# TrainingArguments(...) is still empty, and tests 2.4, 4.1 and 4.2 do not count.
TRAINING_SETTINGS = ("eval_strategy", "save_strategy", "load_best_model_at_end", "metric_for_best_model",
                     "num_train_epochs", "max_steps", "learning_rate", "per_device_train_batch_size", "weight_decay",
                     "warmup_steps", "gradient_accumulation_steps", "lr_scheduler_type")
EMPTY_TRAINING_ARGS = "TrainingArguments in train_router is still empty. Fill it in for this test to count."


def changed_settings(args):
    """The TRAINING_SETTINGS of args that differ from TrainingArguments' defaults."""
    defaults = {f.name: f.default for f in dataclasses.fields(TrainingArguments)}
    return [name for name in TRAINING_SETTINGS
            if name in defaults and plain(getattr(args, name, None)) != plain(defaults[name])]


def toy_sized(value):
    """value, or if it is TrainingArguments, a copy of it sized for the toy data."""
    if not isinstance(value, TrainingArguments):
        return value
    value = copy.copy(value)  # your own object stays as it was
    value.per_device_train_batch_size = min(value.per_device_train_batch_size, TOY_BATCH_SIZE)
    value.gradient_accumulation_steps = 1
    return value


class TrainerRecorder:
    """Records what transformers.Trainer does while train_router runs: its settings when
    training starts, every evaluation, and the state when training ends."""

    def __enter__(self):
        runs = self.runs = []

        class Record(TrainerCallback):
            def __init__(self, run):
                self.run = run

            def on_train_begin(self, args, state, control, **kwargs):
                self.run["args"] = args
                self.run["model"] = kwargs.get("model")

            def on_evaluate(self, args, state, control, metrics=None, **kwargs):
                scores = {k: float(v) for k, v in (metrics or {}).items() if isinstance(v, numbers.Number)}
                self.run["evals"].append({"epoch": float(state.epoch or 0), **scores})

            def on_train_end(self, args, state, control, **kwargs):
                self.run["end"] = {"epoch": float(state.epoch or 0), "best_metric": state.best_metric,
                                   "best_model_checkpoint": state.best_model_checkpoint is not None}

        self.original_init = original_init = Trainer.__init__

        def recording_init(trainer, *args, **kwargs):  # also runs for subclasses, via super().__init__
            original_init(trainer, *map(toy_sized, args), **{k: toy_sized(v) for k, v in kwargs.items()})
            run = {"evals": [], "collator_tokenizer": getattr(trainer.data_collator, "tokenizer", None)}
            runs.append(run)
            trainer.add_callback(Record(run))

        Trainer.__init__ = recording_init
        return self

    def __exit__(self, *exc):
        Trainer.__init__ = self.original_init


class TrainingRun:
    def __init__(self, error=None, run=None, model=None, tokenizer=None, before=None, untrained_logits=None):
        self.error, self.run, self.model, self.tokenizer = error, run, model, tokenizer
        self.before, self.untrained_logits = before, untrained_logits


def train_once(tokenize_record, train_router):
    """Runs the student's train_router on the tiny model and toy data."""
    set_seed(0)
    tokenizer = spy_tokenizer()
    model = AutoModelForSequenceClassification.from_pretrained(TINY_MODEL, num_labels=2)
    before = {k: v.detach().cpu().clone() for k, v in model.state_dict().items()}
    untrained_logits = toy_dev_logits(model)
    # Trainer prints its log; keep it out of the test results.
    with tempfile.TemporaryDirectory() as output_dir, contextlib.redirect_stdout(io.StringIO()), \
            TrainerRecorder() as recorder:
        # The "label" column stays, so training works even if tokenize_record forgets "labels"
        # (the data collator renames label to labels).
        train_ds = tokenized(Dataset.from_dict(toy_rows(256, seed=1)), tokenize_record, tokenizer)
        dev_ds = tokenized(Dataset.from_dict(toy_rows(32, seed=2)), tokenize_record, tokenizer)
        _, error = call_student(train_router, "train_router", model, tokenizer, train_ds, dev_ds, output_dir)
    if error:
        return TrainingRun(error)
    trained = [run for run in recorder.runs if "end" in run]
    if not trained:
        return TrainingRun("train_router should create a Trainer and call trainer.train().")
    return TrainingRun(None, trained[-1], model, tokenizer, before, untrained_logits)

