class TestPartA(unittest.TestCase):
    """Required functions:
        make_records_for_person(name, db_split, title_to_text) -> list of {"text", "label"} records
        text_processing_function(text)               -> str
        tokenize_record(batch, tokenizer, max_length) -> tokenizer output plus "labels"
        compute_metrics(eval_pred)                   -> dict with an "f1" key
        train_router(model, tokenizer, train_ds, dev_ds, output_dir) -> trains with transformers.Trainer and
            returns trainer.model; train_ds and dev_ds are already tokenized with tokenize_record
    """

    def __init__(self, methodName: str = "runTest"):
        super().__init__(methodName)
        self.student_function = None  # make_records_for_person
        self.text_function = None  # text_processing_function
        self.tokenize_record = None
        self.train_router = None
        self.training = None  # the one training run shared by tests 2.4, 3.x and 4.x
        self.use_data(TITLE_TO_TEXT, DB_SPLIT)  # the data set the data-labeling tests (1.x) run on
        self.score = None  # a partial score set by the test; None means all or nothing

    # ---------------------------------------------------------- 1. data labeling
    # Each test runs on the data set chosen by use_data: the made-up test data, or the student's own.

    def use_data(self, title_to_text, db_split, people=None):
        self.title_to_text, self.db_split = title_to_text, db_split
        self.people = list(people) if people else sample_people(title_to_text)
        self.records_cache = {}

    def has_fact(self, name):
        return mentions_fact(name, self.title_to_text, self.db_split)

    def run_ok(self, name):
        """The student's records for name, computed once per data set; fails on an exception."""
        if name not in self.records_cache:
            try:
                with no_text_processing(self.student_function):
                    records = self.student_function(name=name, db_split=dict(self.db_split),
                                                    title_to_text=dict(self.title_to_text))
                self.records_cache[name] = (records, None)
            except Exception as e:
                self.records_cache[name] = (None, f"{FUNCTION_NAME}({name!r}, ...) raised {type(e).__name__}: {e}")
        records, error = self.records_cache[name]
        if error:
            self.fail(error)
        return records

    # 1.1: 3 points, partial credit
    def test_coverage(self):
        """A2b: Prefix coverage"""
        problems, fractions = [], []
        for name in self.people:
            person_problems, fraction = coverage_problems(self.run_ok(name), fact_targets(name))
            if fraction is not None:
                fractions.append(fraction)
            problems += [f"[{name}] {p}" for p in person_problems]
        if not fractions:
            self.fail("No person checked has a positive record, so coverage can't be checked. "
                      "Check your labels, or pass other people with people=[...].")
        self.score = round(POINTS["1.1"] * sum(fractions) / len(fractions), 2)
        if problems:
            self.fail(preview(problems))

    # 1.2: 3 points, partial credit
    def test_labeling(self):
        """A2b: Labels before facts"""
        if self.title_to_text is not TITLE_TO_TEXT:
            return self.check_both_labels()
        counts, problems = [0, 0, 0, 0], []
        for name in self.people:
            *person_counts, person_problems = labeling_counts(self.run_ok(name), fact_targets(name))
            counts = [total + count for total, count in zip(counts, person_counts)]
            problems += [f"[{name}] {p}" for p in person_problems]
        f1 = label_f1(*counts)
        self.score = round(POINTS["1.2"] * min(f1 / MIN_LABEL_F1, 1), 2)
        if f1 < MIN_LABEL_F1:
            self.fail(preview(problems))

    def check_both_labels(self):
        """Test 1.2 on the student's own data, where real facts can span several words or be dates
        written another way: labels must include both 0s and 1s."""
        problems, passed = [], []
        for name in self.people:
            if not self.has_fact(name):
                continue  # no fact to label: all 0s is right
            records = self.run_ok(name)
            person_problems = labeling_problems(records) if isinstance(records, list) else ["Records should be a list."]
            passed.append(not person_problems)
            problems += [f"[{name}] {p}" for p in person_problems]
        if not passed:
            self.fail("No person checked has a db_split fact in their text, so labels can't be checked. "
                      "Pass other people with people=[...].")
        self.score = round(POINTS["1.2"] * sum(passed) / len(passed), 2)
        if problems:
            self.fail(preview(problems))

    # 1.3: 1 point, partial credit
    def test_structure(self):
        """A2b: Record structure"""
        problems, deduction = [], 0
        for name in self.people:
            records = self.run_ok(name)
            if isinstance(records, list) and not records and self.has_fact(name):
                person_problems, person_deduction = ["No records returned, but the text has facts."], 1
            else:
                person_problems, person_deduction = structure_problems(records)
            problems += [f"[{name}] {p}" for p in person_problems]
            deduction = max(deduction, person_deduction)
        self.score = max(POINTS["1.3"] - deduction, 0)
        if problems:
            self.fail(preview(problems))

    # 1.4: 1 point
    def test_title_to_text(self):
        """A2b: Text from title_to_text"""
        problems = []
        for name in self.people:
            records = self.run_ok(name)
            if not isinstance(records, list):
                problems.append(f"[{name}] Records should be a list.")
                continue
            if not records and not self.has_fact(name):
                continue  # no fact in the text: no records is fine
            problems += [f"[{name}] {p}" for p in title_to_text_problems(records, self.title_to_text[name])]
        if problems:
            self.fail(preview(problems) + "\nRead each person's text from title_to_text[name].")

    # 1.5: 1 point
    def test_text_processing(self):
        """A2b: Text processing output"""
        problems = []
        if not callable(self.text_function):
            problems.append(f"{TEXT_FUNCTION_NAME} is not defined. Don't rename or delete it.")
        elif not any(isinstance(records, list) and records for records in map(self.run_ok, self.people)):
            problems.append(f"Skipped until {FUNCTION_NAME} returns records.")
        else:
            for text in text_processing_inputs(self.title_to_text, self.people):
                try:
                    result = self.text_function(text)
                except Exception as e:
                    problems.append(f"{TEXT_FUNCTION_NAME}({text!r}) raised {type(e).__name__}: {e}")
                    continue
                if not isinstance(result, str):
                    problems.append(f"{TEXT_FUNCTION_NAME}({text!r}) should return a str; "
                                    f"got {type(result).__name__}.")
        if problems:
            self.fail(preview(problems))

    # ---------------------------------------------------------- 2.-4. router training

    def trained(self):
        """The shared training run; trains on first use."""
        if self.training is None:
            try:
                self.training = train_once(self.tokenize_record, self.train_router)
            except Exception as e:  # unexpected student output; fail the training tests, not run_all
                self.training = TrainingRun(f"The checks crashed while training ({type(e).__name__}: {e}).")
        if self.training.error:
            self.fail(self.training.error)
        return self.training

    def filled_in_training(self):
        """trained(), failing if TrainingArguments(...) was left empty, as in the starter notebook."""
        training = self.trained()
        if not changed_settings(training.run["args"]):
            self.fail(EMPTY_TRAINING_ARGS)
        return training

    def tokenize(self, texts, labels, max_length, tokenizer=None):
        """Runs tokenize_record on a batch, as dataset.map(batched=True) does. If that fails, runs it
        one example at a time, as dataset.map() does, so either style gets full marks.
        Returns {"input_ids": [...], "labels": [...] or None}, one entry per text."""
        tokenizer = tokenizer or spy_tokenizer()
        try:
            return self._tokenize(texts, labels, max_length, tokenizer)
        except AssertionError:
            raise
        except Exception as e:  # unexpected output, e.g. {"input_ids": 5}
            self.fail(f"{UNREADABLE_TOKENIZE} ({type(e).__name__}: {e}).")

    def _tokenize(self, texts, labels, max_length, tokenizer):
        out, batch_error = call_student(self.tokenize_record, "tokenize_record",
                                        {TEXT_COLUMN: list(texts), LABEL_COLUMN: list(labels)}, tokenizer, max_length)
        rows = None if batch_error else column(out, "input_ids", False)
        if rows is not None and len(rows) == len(texts) and all(isinstance(row, list) for row in rows):
            outs = [(out, False)]
        else:
            outs = []
            for text, label in zip(texts, labels):
                one, error = call_student(self.tokenize_record, "tokenize_record",
                                          {TEXT_COLUMN: text, LABEL_COLUMN: label}, tokenizer, max_length)
                if error:
                    self.fail(error if error == batch_error else
                              f"tokenize_record failed on a batch (dataset.map(batched=True)): "
                              f"{batch_error or 'it did not return one row per text'}\n"
                              f"and on a single example (dataset.map()): {error}")
                outs.append((one, True))
        missing = sorted({k for o, _ in outs for k in ("input_ids", "attention_mask") if column(o, k, False) is None})
        if missing:
            self.fail(f"tokenize_record should return the tokenizer output; missing {missing}.")
        result = {}
        for key in ("input_ids", "labels"):
            parts = [column(o, key, single) for o, single in outs]
            result[key] = None if any(p is None for p in parts) else [row for p in parts for row in p]
        return result

    # 2.1: 2 points
    def test_tokenize_uses_given_tokenizer(self):
        """A3b: Given tokenizer"""
        loads = pretrained_loads(self.tokenize_record, "Tokenizer")
        if loads:
            self.fail(f"tokenize_record should use the tokenizer argument, not load its own ({', '.join(loads)}).")
        tokenizer = spy_tokenizer()
        self.tokenize(["a short query"], [0], 16, tokenizer)
        if not tokenizer.text_calls:
            self.fail("tokenize_record should call the tokenizer argument.")

    # 2.2: 1 point
    def test_tokenize_truncates(self):
        """A3b: Truncation"""
        for max_length in (16, 32):
            longest = len(self.tokenize(["a short query", LONG_TEXT], [0, 1], max_length)["input_ids"][1])
            if longest != max_length:
                self.fail(f"With max_length={max_length}, a 300-word text should have {max_length} tokens; "
                          f"got {longest}.")

    # 2.3: 2 points
    def test_tokenize_adds_labels(self):
        """A3b: Labels"""
        labels = self.tokenize(["a short query", "another query", "a third"], [1, 0, 1], 16)["labels"]
        if labels is None:
            self.fail(f'The output should include batch["{LABEL_COLUMN}"] under the key "labels".')
        if [int(x) for x in flat(labels)] != [1, 0, 1]:
            self.fail(f'"labels" should match batch["{LABEL_COLUMN}"] in order; got {labels}.')

    # 2.4: 1 point
    def test_train_router_uses_given_tokenizer(self):
        """A3d: Given tokenizer"""
        loads = pretrained_loads(self.train_router, "Tokenizer")
        if loads:
            self.fail(f"train_router should use the tokenizer argument, not load its own ({', '.join(loads)}).")
        training = self.filled_in_training()
        collator_tokenizer = training.run["collator_tokenizer"]
        if collator_tokenizer is not None and collator_tokenizer is not training.tokenizer:
            self.fail("The data collator should use the tokenizer argument: DataCollatorWithPadding(tokenizer).")

    # 3.1: 2 points
    def test_evaluates_every_epoch(self):
        """A3d: Evaluation every epoch"""
        run = self.trained().run
        strategy = getattr(run["args"], "eval_strategy", None) or getattr(run["args"], "evaluation_strategy", None)
        strategy = getattr(strategy, "value", strategy)
        if strategy != "epoch":
            self.fail(f'eval_strategy should be "epoch"; got "{strategy}".')
        epochs = round(run["end"]["epoch"])
        evaluated = sorted({round(e["epoch"]) for e in run["evals"] if "eval_loss" in e})
        if evaluated != list(range(1, epochs + 1)):
            self.fail(f"Should evaluate after every epoch; trained {epochs} epoch(s), evaluated after "
                      f"{evaluated}. Pass dev_ds as eval_dataset.")

    # 3.2: 2 points
    def test_best_checkpoint_by_dev_f1(self):
        """A3d: Best checkpoint by F1"""
        run = self.trained().run
        args, end = run["args"], run["end"]
        if not args.load_best_model_at_end:
            self.fail("load_best_model_at_end should be True.")
        if args.metric_for_best_model not in ("f1", "eval_f1"):
            self.fail(f'metric_for_best_model should be "f1"; got {args.metric_for_best_model!r}.')
        if args.greater_is_better is False:
            self.fail("greater_is_better should not be False: higher F1 is better.")
        scores = [e["eval_f1"] for e in run["evals"] if "eval_f1" in e]
        if not scores:
            self.fail('Evaluation should report eval_f1. Pass compute_metrics to Trainer and return {"f1": ...}.')
        if not end["best_model_checkpoint"]:
            self.fail('No best checkpoint was saved. Set save_strategy="epoch".')
        if round(abs(end["best_metric"] - max(scores)), 6) != 0:
            self.fail(f"The best checkpoint should have the highest dev F1 ({max(scores)}); "
                      f"got {end['best_metric']}.")

    # 4.1: 2 points
    def test_model_learned(self):
        """A3d: Model learns"""
        loads = pretrained_loads(self.train_router, "Model")
        if loads:
            self.fail(f"train_router should train the model argument, not load its own ({', '.join(loads)}).")
        training = self.filled_in_training()
        if training.run.get("model") is not training.model:
            self.fail("Trainer should train the model argument: Trainer(model=model, ...).")
        after = training.model.state_dict()
        if all(v.equal(after[k].detach().cpu()) for k, v in training.before.items()):
            self.fail("The model's weights did not change, so it was not trained.")
        limit = best_bias_only_loss(training.untrained_logits) - MIN_LOSS_DROP
        loss = toy_dev_loss(toy_dev_logits(training.model))
        if loss >= limit:
            self.fail(f"Toy dev loss should be below {limit:.4f} (just under an untrained model's best using only "
                      f"the output bias); got {loss:.4f}. Check that labels reach the model and that training runs "
                      "at least one epoch.")

    # 4.2: 2 points
    def test_predicts_both_classes(self):
        """A3d: Separates both classes"""
        logits = toy_dev_logits(self.filled_in_training().model)
        predicted = sorted(set(logits.argmax(-1).tolist()))
        if predicted != [0, 1] and toy_dev_auc(logits) < MIN_TOY_AUC:
            self.fail(f"The trained model should predict both 0 and 1 on toy data; got only {predicted}. "
                      "Check the learning rate and that labels reach the model.")

# ------------------------
#  Run all tests in notebook.
# ------------------------

def run_tests(t, tests):
    """Runs each (number, test) on t, prints its score and problem, and returns the points earned."""
    total = 0
    for number, test in tests:
        t.score = None
        problem = None
        try:
            test()
            score = POINTS[number] if t.score is None else t.score
        except Exception as e:  # a failed check, or the check itself crashed on unexpected output
            problem = str(e) if isinstance(e, AssertionError) else f"{type(e).__name__}: {e}"
            score = t.score or 0
        print(f"{number} {test.__doc__}: {score:g}/{POINTS[number]:g}")
        if problem:
            print("  " + problem.replace("\n", "\n  "))
        total += score
    return total


# The student functions Gradescope calls, and the notebook globals it supplies for them.
STUDENT_FUNCTIONS = (FUNCTION_NAME, TEXT_FUNCTION_NAME, "tokenize_record", "train_router")
SUPPLIED_GLOBALS = {"nlp", "SELECTED_RELATIONS", "CLOSED_CLASS_POS", "db_clean_train", "List", "Dict"}


def notebook_definitions(cells):
    """{name: its top-level statement} for what Gradescope runs: imports, functions, classes and
    literal constants. A later definition wins."""
    definitions = {}
    for cell in cells:
        source = "".join("\n" if line.lstrip().startswith(("!", "%")) else line
                         for line in cell.splitlines(keepends=True))
        try:
            tree = ast.parse(source)
        except SyntaxError:
            continue
        for node in tree.body:
            if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                definitions[node.name] = node
            elif isinstance(node, (ast.Import, ast.ImportFrom)):
                definitions.update({alias.asname or alias.name.split(".")[0]: node for alias in node.names})
            elif isinstance(node, (ast.Assign, ast.AnnAssign)) and node.value is not None:
                try:
                    ast.literal_eval(node.value)
                except (ValueError, TypeError):
                    continue
                targets = node.targets if isinstance(node, ast.Assign) else [node.target]
                definitions.update({target.id: node for target in targets if isinstance(target, ast.Name)})
    return definitions


def global_names(node):
    """The global names a top-level statement uses, including inside nested functions."""
    def collect(scope):
        names = {symbol.get_name() for symbol in scope.get_symbols() if symbol.is_referenced()
                 and (scope.get_type() == "module" or symbol.is_global())}
        for child in scope.get_children():
            names |= collect(child)
        return names

    return collect(symtable.symtable(ast.unparse(node), "<notebook>", "exec"))


def missing_on_gradescope(cells):
    """{student function: notebook variables it uses that Gradescope will not have}."""
    definitions = notebook_definitions(cells)
    found = {}
    for root in STUDENT_FUNCTIONS:
        seen, todo = set(), [root] if root in definitions else []
        while todo:
            name = todo.pop()
            if name in seen or name in SUPPLIED_GLOBALS:
                continue
            seen.add(name)
            if name in definitions:
                todo += global_names(definitions[name])
            elif not hasattr(builtins, name):
                found.setdefault(root, set()).add(name)
    return found


def run_all(make_records_for_person, text_processing_function, title_to_text, db_split, tokenize_record,
            train_router, people=None):
    """Run every test, print each result, and return the total score.

    The data-labeling tests (1.x) run twice: on the made-up test data, as on Gradescope, and on your
    title_to_text and db_split, for NUM_PEOPLE people sampled from them (or for `people`, a list of
    names). Only the first run counts toward the total, because Gradescope does not have your data."""
    t = TestPartA()
    t.student_function = make_records_for_person
    t.text_function = text_processing_function
    t.tokenize_record = tokenize_record
    t.train_router = train_router
    labeling_tests = [
        ("1.1", t.test_coverage),
        ("1.2", t.test_labeling),
        ("1.3", t.test_structure),
        ("1.4", t.test_title_to_text),
        ("1.5", t.test_text_processing),
    ]
    router_tests = [
        ("2.1", t.test_tokenize_uses_given_tokenizer),
        ("2.2", t.test_tokenize_truncates),
        ("2.3", t.test_tokenize_adds_labels),
        ("2.4", t.test_train_router_uses_given_tokenizer),
        ("3.1", t.test_evaluates_every_epoch),
        ("3.2", t.test_best_checkpoint_by_dev_f1),
        ("4.1", t.test_model_learned),
        ("4.2", t.test_predicts_both_classes),
    ]
    labeling_points = sum(POINTS[number] for number, _ in labeling_tests)

    # In is the notebook's cell history. A plain script has none, so it gets no warning.
    missing = missing_on_gradescope(getattr(make_records_for_person, "__globals__", {}).get("In", []))
    if missing:
        print("These notebook variables won't exist on Gradescope, which runs only imports, functions, "
              "classes, and constants. Use the function's arguments instead:")
        for name, variables in missing.items():
            print(f"  {name} uses {', '.join(sorted(variables))}")
        print()

    print("Part A self-tests")
    print("Data labeling, test data (counted, as on Gradescope)")
    t.use_data(TITLE_TO_TEXT, DB_SPLIT)
    total = run_tests(t, labeling_tests)

    t.use_data(title_to_text, db_split, people)
    print(f"\nData labeling, your data: {len(t.people)} people (not counted)")
    yours = run_tests(t, labeling_tests)
    print(f"Your data: {yours:g}/{labeling_points:g}")

    print("\nRouter training")
    total += run_tests(t, router_tests)
    print(f"Total: {total:g}/{sum(POINTS.values()):g}")
    return total
